"""Data types shared across the cross-phase correction sub-module."""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, ConfigDict

from rasa.mantle.memory.field import MemoryField


class CorrectableMemoryItem(BaseModel):
    """A memory item eligible for cross-phase correction this turn.

    Attributes:
        memory_key: Identifier of the memory item the LLM passes as
            ``correct(memory_key=...)``. It is the fully-qualified memory key
            resolved by the memory manager (e.g. ``card_replace.shipping_type``),
            kept here only so the dispatcher can match the LLM's choice back to
            this item — this module never parses or constructs it.
        entry_name: Bare memory entry name (e.g. ``shipping_type``).
        skill_id: Skill that owns the memory entry (the skill whose
            ``memory.yml`` declares it). Writes, memory validation tools, and
            producer lookup use this id — not the skill of the stack frame
            that happened to stamp the latest memory write.
        flow_id: Flow id of the producing frame (replay identity). This is
            the flow that wrote the value, which may belong to an ancestor
            when a parent frame stamps a child-owned slot. It is not
            necessarily a flow of ``skill_id``.
        frame_id: Id of the stack frame that produced the value — the rewind
            target for replay drivers. For a ``requires_reentry`` item this is
            the id of the *completed* sub-skill frame (no longer on the
            current stack), recovered from write-provenance.
        step_id: Id of the collect step that produced the value.
        field: Static field declaration (type, description, enum values).
        resolved_description: Description the model sees for this field. The
            collect-step description when that step has one, otherwise the
            memory-field description.
        current_value: The value being corrected away from.
        requires_reentry: ``True`` when the producing frame is a sub-skill that
            already completed and popped, so applying the correction must
            *re-enter* it by reconstructing the stack from history rather than
            repositioning a frame still on the stack.
    """

    model_config = ConfigDict(frozen=True)

    memory_key: str
    entry_name: str
    skill_id: str
    flow_id: str
    frame_id: str
    step_id: str
    field: MemoryField
    resolved_description: str | None = None
    current_value: Any = None
    requires_reentry: bool = False
